package id.sapu.berita;

import android.content.Context;
import android.net.Uri;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Which links stay in Sapu Berita. Generated by `npm run build` into assets/domains.json from the same
 * rules the cleaner uses, so adding an outlet to rules/ is all it takes.
 */
final class NewsSites {
    private static NewsSites instance;

    private final List<String> domains = new ArrayList<>();
    private final List<Pattern> patterns = new ArrayList<>();

    static synchronized NewsSites get(Context context) {
        if (instance == null) instance = new NewsSites(context.getApplicationContext());
        return instance;
    }

    private NewsSites(Context context) {
        try (InputStream in = context.getAssets().open("domains.json")) {
            JSONObject json = new JSONObject(readAll(in));
            JSONArray d = json.getJSONArray("domains");
            for (int i = 0; i < d.length(); i++) domains.add(d.getString(i).toLowerCase(Locale.ROOT));
            JSONArray p = json.optJSONArray("patterns");
            if (p != null) {
                for (int i = 0; i < p.length(); i++) {
                    try {
                        patterns.add(Pattern.compile(p.getString(i)));
                    } catch (RuntimeException ignored) {
                        // A pattern Java can't compile only means that outlet opens in the normal browser.
                    }
                }
            }
        } catch (Exception e) {
            // No asset (a build without `npm run build`): nothing is treated as news; every link is forwarded.
        }
    }

    boolean isNews(Uri uri) {
        if (uri == null) return false;
        String scheme = uri.getScheme();
        if (!"https".equals(scheme) && !"http".equals(scheme)) return false;
        String host = uri.getHost();
        if (host == null) return false;
        host = host.toLowerCase(Locale.ROOT);
        for (String d : domains) {
            if (host.equals(d) || host.endsWith("." + d)) return true;
        }
        for (Pattern p : patterns) {
            if (p.matcher(host).find()) return true;
        }
        return false;
    }

    private static String readAll(InputStream in) throws java.io.IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        for (int n; (n = in.read(buf)) > 0; ) out.write(buf, 0, n);
        return out.toString(StandardCharsets.UTF_8.name());
    }
}
